@pytest.mark.parametrize("mutation", ["converged", "live", "failed", "historical_step", "cache_count", "new_chain", "DFT", "physical", "holdout", "FIRE", "manifest_type", "seed_file", "runtime", "observation", "receipt_observation", "SCF_count", "source", "unknown_parent"]) def test_unauthorized_or_changed_recipe_rejects(tmp_path, mutation, monkeypatch): parent = "28723655" seed, audit, runtime, source = fixture(tmp_path, parent) manifest, receipt = [json.loads(p.read_text()) for p in (seed, audit)] if mutation == "converged": receipt["ordinary_converged"] = True elif mutation in ("live", "failed"): receipt["scheduler_row"] = receipt["scheduler_row"].replace("COMPLETED", mutation.upper()) elif mutation == "historical_step": manifest["source_step"] = 35 elif mutation == "cache_count": receipt["current_frame_exact_caches_checked"] = 8 elif mutation == "new_chain": manifest["new_independent_chains"] = 1 elif mutation == "DFT": receipt["new_DFT_calls"] = 1 elif mutation == "physical": manifest["physical_inputs_changed"] = True elif mutation == "holdout": receipt["holdout_generated_or_read"] = True elif mutation == "FIRE": receipt["FIRE_state_restored"] = True elif mutation == "manifest_type": manifest["new_DFT_calls"] = False # not integer0 elif mutation == "seed_file": (seed.parent/"seed.traj").write_text("changed") elif mutation == "runtime": (runtime/"vcneb/material_runner.py").write_text("changed") elif mutation == "observation": (audit.parent/"observations/step_0040/observation.json").write_text("changed") elif mutation == "receipt_observation": receipt["terminal_observation"] = {"changed": True} elif mutation == "SCF_count": receipt["fresh_interior_SCFs"] = 77 elif mutation == "source": source += "/different" else: parent = "28709790" # existing held starter is not a completed parent write_json(seed, manifest) receipt["seed_manifest_sha256"] = digest(seed) write_json(audit, receipt) with pytest.raises(ValueError): > run_validator(seed, audit, runtime, source, parent, monkeypatch)
